class Mutex {
  constructor() {
    this.locked = false;
    this.queue = [];
  }

  acquire() {
    // TODO: return a Promise. If not locked, lock it and resolve immediately.
    // If already locked, push the resolver onto this.queue instead.
  }

  release() {
    if (this.queue.length > 0) {
      const next = this.queue.shift();
      next();
    } else {
      this.locked = false;
    }
  }
}

items.solution:
acquire() {
  return new Promise((resolve) => {
    if (!this.locked) {
      this.locked = true;
      resolve();
    } else {
      this.queue.push(resolve);
    }
  });
}
